window.P2_UNITS = [
{ n:1, title:"RELATIONSHIPS", pages:"1\u201312", level:"The Phrasal-Verb Frontier", color:"#c0392b", theme:"Friendship, opinions and disagreeing politely",
  overview:{
    intro:"This unit is about the people around you \u2014 how friendships start, how they break, and how they get repaired. At C1 level the challenge is no longer describing people, but talking about relationships with nuance: hedging, softening, and disagreeing without causing offence.",
    goals:["Describe how relationships begin, change and end using phrasal verbs naturally.","Choose correctly between gerund and infinitive after common verbs.","Disagree politely and hold your position in a discussion."],
    outcome:"By the end you can tell a detailed anecdote about a friendship over time, and take part in a disagreement using at least three softening expressions."
  },
  vocab:[
    {term:"acquaintance", pos:"noun", def:"a person you know slightly, but who is not a close friend.",
     use:"Use it when \u2018friend\u2019 would be too strong \u2014 a workmate you chat with, a neighbour you greet in the lift.",
     examples:["She\u2019s an acquaintance from my old job, not someone I\u2019d call at midnight.","We were acquaintances for two years before we became real friends."],
     colloc:"a mutual acquaintance \u00b7 a business acquaintance \u00b7 a passing acquaintance"},
    {term:"to hit it off", pos:"phrasal verb (informal)", def:"to like someone and become friendly the moment you meet.",
     use:"Almost always used with \u2018straight away / immediately\u2019, and the object is always \u2018it\u2019 \u2014 never \u2018hit off him\u2019.",
     examples:["We hit it off straight away and talked for three hours.","They didn\u2019t hit it off at first, but now they\u2019re inseparable."],
     colloc:"hit it off immediately \u00b7 hit it off with someone \u00b7 really hit it off"},
    {term:"to fall out (with)", pos:"phrasal verb", def:"to argue and stop being friendly with someone.",
     use:"The reason takes \u2018over\u2019: you fall out WITH a person OVER a thing. The opposite is \u2018make up\u2019.",
     examples:["I fell out with my cousin over an inheritance.","They fell out years ago and never made up."],
     colloc:"fall out with someone \u00b7 fall out over money \u00b7 a falling-out (noun)"},
    {term:"to see eye to eye", pos:"idiom", def:"to agree completely with someone.",
     use:"Most common in the negative: \u2018we don\u2019t see eye to eye on\u2026\u2019 is a diplomatic way of admitting disagreement.",
     examples:["We don\u2019t see eye to eye on politics, so we avoid the subject.","On money matters we\u2019ve always seen eye to eye."],
     colloc:"see eye to eye with someone \u00b7 see eye to eye on something"},
    {term:"to come across as", pos:"phrasal verb", def:"to give a certain impression to other people.",
     use:"About the impression given, not the reality \u2014 so it pairs well with \u2018although in fact\u2026\u2019.",
     examples:["He comes across as arrogant, although he\u2019s actually shy.","In interviews, try to come across as confident but humble."],
     colloc:"come across as rude / friendly / confident \u00b7 come across well"},
    {term:"to beg to differ", pos:"fixed expression (formal)", def:"a polite, slightly formal way of saying you disagree.",
     use:"Use it in a meeting or debate when you want to push back firmly but stay courteous. It sounds odd in casual chat with close friends.",
     examples:["I\u2019m afraid I beg to differ \u2014 the data suggests the opposite.","You say the plan is safe; I beg to differ."],
     colloc:"I beg to differ \u00b7 I\u2019d beg to differ on that point"} ],
  grammar:[
    {name:"Phrasal verbs", short:"Verb + particle, often idiomatic \u2014 and sometimes separable.",
     rule:"A phrasal verb is a verb + one or two particles (up, out, on, up with\u2026) whose meaning is usually idiomatic: you cannot work out \u2018put up with\u2019 from \u2018put\u2019 + \u2018up\u2019 + \u2018with\u2019.",
     form:["Separable: turn the TV off / turn off the TV / turn it off.","Inseparable: look after the kids / look after them (never \u2018look the kids after\u2019).","Three-part verbs are always inseparable: put up with him, get on with it."],
     notes:["With a PRONOUN object, a separable phrasal verb must split: \u2018turn it off\u2019, not \u2018turn off it\u2019.","With a long noun phrase, keep the particle close to the verb: \u2018She brought up the question of money\u2019 sounds better than \u2018brought the question of money up\u2019.","Phrasal verbs are informal; in academic writing the one-word equivalent (tolerate, admire, discover) is often preferred."],
     examples:["We fell out over politics, but we soon made up.","You should look up to people who treat others well.","I just can\u2019t put up with rude behaviour."],
     watch:"Don\u2019t memorise bare lists. Learn each phrasal verb inside a short sentence that shows who does what to whom."},
    {name:"Gerund & infinitive constructions", short:"Which verbs take -ing, which take to + verb, and which change meaning.",
     rule:"Some verbs are followed by a gerund (enjoy, avoid, mind, suggest), others by an infinitive (decide, hope, offer, refuse). A small group takes both, with a change of meaning.",
     form:["Verb + -ing: enjoy meeting, avoid arguing, don\u2019t mind waiting.","Verb + to: decide to leave, hope to see, offer to help.","Preposition + -ing (always): interested in meeting, good at listening, instead of calling."],
     notes:["stop doing = end the activity / stop to do = pause in order to do it.","remember to do = don\u2019t forget (future) / remember doing = have a memory (past).","try to do = make an effort / try doing = experiment with it as a solution."],
     examples:["I really enjoy hanging out with my cousins.","She decided to apologise first.","Remember to text me (don\u2019t forget) vs I remember texting you (a memory)."],
     watch:"After a preposition, English always uses -ing: \u2018before leaving\u2019, never \u2018before to leave\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"In pairs: two old friends who fell out years ago meet again at a wedding in Cartagena. Rebuild the friendship, disagreeing politely about whose fault it was."},
    {kind:"Debate", text:"Half the class argues that online friends can be just as close as offline friends; the other half disagrees. Use \u2018I see your point, but\u2026\u2019 and \u2018I beg to differ\u2019."},
    {kind:"Pair work", text:"Describe your best friend: how did you meet, how did you hit it off, and when do you not see eye to eye?"} ],
  tips:[
    "Disagree politely with softeners: \u2018I see what you mean, but\u2026\u2019, \u2018I\u2019m not so sure about that\u2019, \u2018With respect, I\u2019d say\u2026\u2019.",
    "Learn phrasal verbs in short example sentences, not as bare lists \u2013 the context makes the meaning stick.",
    "Common slip: with a pronoun, separable phrasal verbs MUST split \u2013 say \u2018turn it off\u2019, never \u2018turn off it\u2019."],
  quiz:{q:"My sister and I ___ over money last year, but we\u2019re fine now.", options:["fell out","fell in","fell off"], answer:0, explain:"\u2018Fall out (with someone)\u2019 means to argue and stop being friendly."} },

{ n:2, title:"CLOTHES & APPEARANCE", pages:"13\u201324", level:"The Cleft-Sentence Catwalk", color:"#1f8a7a", theme:"Fashion, style and first impressions",
  overview:{
    intro:"Appearance is a socially delicate topic, so this unit trains you to comment on how people look without sounding rude, and to emphasise what matters to you. Cleft sentences are the key tool: they let you spotlight one idea inside a longer sentence.",
    goals:["Talk about clothes, style and impressions with precise, non-judgemental vocabulary.","Control verb patterns with object + infinitive / object + -ing.","Emphasise a key point using \u2018What\u2026 is / was\u2026\u2019 structures."],
    outcome:"By the end you can give style advice and defend a position on first impressions, using at least two cleft sentences for emphasis."
  },
  vocab:[
    {term:"to dress up / dress down", pos:"phrasal verbs", def:"to wear smarter clothes / to wear more casual clothes.",
     use:"\u2018Dress up\u2019 can also mean wear a costume, so context matters. \u2018Dress down\u2019 is often about a workplace rule (\u2018dress-down Friday\u2019).",
     examples:["Do we need to dress up for the dinner, or is it casual?","The office lets us dress down on Fridays."],
     colloc:"dress up for an occasion \u00b7 dressed up to the nines \u00b7 a dress-down day"},
    {term:"understated", pos:"adjective", def:"stylish in a subtle, quiet way that doesn\u2019t show off.",
     use:"A compliment. Its opposites \u2018flashy\u2019 and \u2018over the top\u2019 are usually criticism.",
     examples:["Her look was understated \u2014 one good coat and no jewellery.","He prefers understated elegance to designer logos."],
     colloc:"understated elegance \u00b7 an understated look \u00b7 quietly understated"},
    {term:"to pull off (a look)", pos:"phrasal verb (informal)", def:"to wear successfully something that could be hard to wear.",
     use:"Implies difficulty: only risky clothes need to be \u2018pulled off\u2019. It also means \u2018succeed at something difficult\u2019 in general.",
     examples:["Not everyone can pull off a bright yellow suit.","She pulled the whole vintage look off perfectly."],
     colloc:"pull off a look \u00b7 pull it off \u00b7 hard to pull off"},
    {term:"hand-me-downs", pos:"noun (plural)", def:"used clothes passed down from an older person to a younger one.",
     use:"Usually about siblings or cousins. Neutral to slightly humorous, not insulting.",
     examples:["As the youngest of four, I lived in hand-me-downs.","These jeans are hand-me-downs from my brother."],
     colloc:"wear hand-me-downs \u00b7 hand-me-down clothes"},
    {term:"trendsetter", pos:"noun", def:"someone who starts new fashions that others copy.",
     use:"Positive. The adjective is \u2018trendsetting\u2019; the follower is a \u2018follower of fashion\u2019.",
     examples:["Local designers here are real trendsetters.","She was a trendsetter long before the brands noticed."],
     colloc:"a real trendsetter \u00b7 a trendsetting designer"},
    {term:"to judge a book by its cover", pos:"idiom", def:"to form an opinion of someone based only on appearance.",
     use:"Nearly always used as a warning: \u2018don\u2019t judge a book by its cover\u2019.",
     examples:["Don\u2019t judge a book by its cover \u2014 he\u2019s the best coder here.","We all judge books by their covers, whether we admit it or not."],
     colloc:"don\u2019t judge a book by its cover"} ],
  grammar:[
    {name:"Review of verb patterns", short:"make / let / want / see + object + verb.",
     rule:"Many verbs are followed by an object plus a verb form. Which form depends on the verb: to-infinitive, bare infinitive, or -ing.",
     form:["Object + to-infinitive: want / expect / tell / advise someone TO do.","Object + bare infinitive: make / let / have someone DO.","Object + -ing or bare infinitive: see / hear / watch someone DO (whole action) or DOING (in progress)."],
     notes:["\u2018Make\u2019 loses \u2018to\u2019 in the active but keeps it in the passive: \u2018They made him wait\u2019 \u2192 \u2018He was made to wait\u2019.","\u2018Let\u2019 has no passive; use \u2018be allowed to\u2019 instead.","Choose -ing to stress that the action was in progress: \u2018I saw her trying on the coat\u2019."],
     examples:["I want you to try this jacket on.","The dress code makes everyone wear a suit.","I saw her wearing that exact coat yesterday."],
     watch:"Never say \u2018make someone to do\u2019 in the active voice."},
    {name:"Cleft sentences with what", short:"Front the key idea: \u2018What I love is\u2026\u2019.",
     rule:"A cleft sentence splits one idea into two clauses so you can spotlight the important part. Put \u2018What + clause\u2019 first, then a form of \u2018be\u2019, then the highlighted information.",
     form:["What I love about her style IS the confidence.","What really caught my eye WAS the red coat.","What we need IS a look that says \u2018professional\u2019."],
     notes:["The verb \u2018be\u2019 agrees with what follows it: \u2018What I need is a suit\u2019 / \u2018What I need are new shoes\u2019.","You can also cleft with \u2018It was\u2026 that\u2026\u2019 (\u2018It was the coat that caught my eye\u2019) or \u2018All I want is\u2026\u2019.","To highlight an action, use \u2018What she did was (to) change\u2026\u2019."],
     examples:["What I love about her style is the confidence.","What really caught my eye was the bright red coat.","What we need is a look that says \u2018professional\u2019."],
     watch:"Use \u2018What\u2019, not \u2018Which\u2019 or \u2018That\u2019, to open this structure."} ],
  speaking:[
    {kind:"Role-play", text:"In pairs: a personal shopper in a Medell\u00edn boutique advises a nervous client on what to wear to an international job interview."},
    {kind:"Debate", text:"This house believes first impressions matter too much. Argue for or against, using cleft sentences to emphasise your points."},
    {kind:"Pair work", text:"Tell a partner about a time an outfit changed how people treated you. What did you pull off \u2013 or fail to pull off?"} ],
  tips:[
    "Use cleft sentences to add emphasis in a presentation: \u2018What matters most is\u2026\u2019.",
    "\u2018Understated\u2019 usually sounds like a compliment; \u2018overdressed\u2019 and \u2018flashy\u2019 are negative.",
    "Common slip: it\u2019s \u2018judge a book BY its cover\u2019, not \u2018for its cover\u2019."],
  quiz:{q:"___ really caught my eye was the bright red coat.", options:["What","Which","That"], answer:0, explain:"Cleft sentences for emphasis begin with \u2018What + clause + be\u2019."} },

{ n:3, title:"SCIENCE & TECHNOLOGY", pages:"25\u201336", level:"The Article Laboratory", color:"#d99413", theme:"Scientific advances and attitudes toward technology",
  overview:{
    intro:"Talking about science means talking in generalisations \u2014 and that is exactly where articles go wrong. This unit fixes a/an, the and zero article, then adds -ing clauses so your writing sounds concise and academic instead of a chain of short sentences.",
    goals:["Discuss innovations, benefits and drawbacks with precise vocabulary.","Use a / an / the / no article correctly with general and specific nouns.","Combine ideas economically with -ing clauses."],
    outcome:"By the end you can present a new technology, weigh its drawbacks, and write a short paragraph using two -ing clauses."
  },
  vocab:[
    {term:"breakthrough", pos:"noun", def:"an important discovery or development.",
     use:"Reserved for genuinely big steps forward \u2014 usually in science, medicine or negotiation.",
     examples:["The vaccine was a major breakthrough.","After months of talks, there was finally a breakthrough."],
     colloc:"a major / scientific / medical breakthrough \u00b7 make a breakthrough"},
    {term:"cutting-edge", pos:"adjective", def:"the most advanced and modern.",
     use:"Goes before the noun; as a noun phrase say \u2018at the cutting edge of\u2019 (no hyphen).",
     examples:["The lab uses cutting-edge imaging equipment.","They are at the cutting edge of battery research."],
     colloc:"cutting-edge technology / research \u00b7 at the cutting edge of"},
    {term:"to roll out", pos:"phrasal verb", def:"to introduce a new product or service gradually.",
     use:"Suggests stages or regions, not a single launch day. The noun is \u2018a rollout\u2019.",
     examples:["They\u2019ll roll the app out city by city.","The rollout starts in Bogot\u00e1 next month."],
     colloc:"roll out a service \u00b7 a nationwide rollout \u00b7 a phased rollout"},
    {term:"a game-changer", pos:"noun (informal)", def:"something that completely changes a situation.",
     use:"Common in business and tech talk; slightly overused, so use it for real shifts.",
     examples:["Cheap solar panels were a game-changer for the region.","Remote work has been a game-changer for parents."],
     colloc:"a real game-changer \u00b7 prove to be a game-changer"},
    {term:"obsolete", pos:"adjective", def:"no longer used because something better now exists.",
     use:"Stronger and more formal than \u2018old\u2019: an obsolete device is not just old, it has been replaced.",
     examples:["Fax machines are almost obsolete.","New standards made the old software obsolete overnight."],
     colloc:"become / render something obsolete \u00b7 technically obsolete"},
    {term:"drawback", pos:"noun", def:"a disadvantage or problem.",
     use:"Slightly softer and more analytical than \u2018problem\u2019 \u2014 ideal for balanced essays.",
     examples:["The main drawback is the price.","Every solution has its drawbacks."],
     colloc:"the main / only / obvious drawback \u00b7 have a drawback"} ],
  grammar:[
    {name:"Indefinite & definite articles", short:"a / an, the, and no article at all.",
     rule:"Use \u2018a/an\u2019 to introduce a non-specific singular countable noun, \u2018the\u2019 when the noun is specific, already mentioned, or unique, and no article for general plurals and uncountables.",
     form:["First mention, one of many: A breakthrough was announced.","Specific or unique: THE breakthrough we discussed / THE internet / THE sun.","General truth, plural or uncountable: Technology changes fast. Robots are cheaper now."],
     notes:["\u2018The\u2019 also appears with superlatives, ordinals and \u2018only\u2019: the best result, the first trial, the only option.","Institutions used generally take no article: go to university / be in hospital (UK).","\u2018a\u2019 vs \u2018an\u2019 follows the SOUND: a university, an hour, an MRI scan."],
     examples:["A breakthrough was announced this morning.","The internet has transformed how we learn.","Technology changes faster than laws can keep up."],
     watch:"Don\u2019t add \u2018the\u2019 to a general uncountable: \u2018Water is essential\u2019, not \u2018The water is essential\u2019."},
    {name:"-ing clauses", short:"Compress two sentences into one.",
     rule:"An -ing clause replaces a full clause of reason, time or accompanying action, as long as both clauses share the same subject.",
     form:["Reason: Feeling curious, she opened the app. (= Because she felt curious\u2026)","Time: Opening the report, he noticed the error. (= When he opened\u2026)","Extra information inside a sentence: The report, showing a clear trend, surprised everyone."],
     notes:["For negatives, put \u2018not\u2019 first: Not knowing the password, he gave up.","For an earlier action, use \u2018having + past participle\u2019: Having tested the device, they published the results.","If the subjects differ the sentence dangles: \u2018Feeling curious, the app was opened\u2019 is wrong."],
     examples:["Feeling curious, the students opened the app.","The report, showing a clear trend, surprised everyone.","Not knowing the password, he gave up."],
     watch:"Keep the same subject in both halves \u2014 that is the number-one -ing clause error."} ],
  speaking:[
    {kind:"Role-play", text:"Two engineers pitch a new app to investors at a Bogot\u00e1 startup expo. The investors keep asking about the drawbacks."},
    {kind:"Debate", text:"Artificial intelligence will do more good than harm. Take a side and defend it with examples."},
    {kind:"Pair work", text:"Tell a partner about one piece of technology you couldn\u2019t live without \u2013 and one you think is already obsolete."} ],
  tips:[
    "Say \u2018the internet\u2019, \u2018the environment\u2019 \u2013 these take \u2018the\u2019. But general \u2018technology\u2019 / \u2018science\u2019 take no article.",
    "-ing clauses make writing sound more advanced \u2013 use them to combine two short sentences.",
    "Common slip: don\u2019t add \u2018the\u2019 to a general uncountable \u2013 \u2018Water is essential\u2019, not \u2018The water is essential\u2019 (in general)."],
  quiz:{q:"___ internet has completely changed the way we study.", options:["The","A","(no article)"], answer:0, explain:"\u2018The internet\u2019 is a unique thing, so it takes the definite article \u2018the\u2019."} },

{ n:4, title:"SUPERSTITIONS & BELIEFS", pages:"37\u201349", level:"The Reported-Speech S\u00e9ance", color:"#7d4b6b", theme:"Personal beliefs, luck and hoaxes",
  overview:{
    intro:"Beliefs are usually somebody else\u2019s claims, so this unit is built on reporting: what people say, what is said in general, and how much distance you keep from the claim. Impersonal passive reporting is the C1 skill that makes you sound objective.",
    goals:["Describe superstitions, hoaxes and levels of belief accurately.","Report speech with correct tense, pronoun and time-word shifts.","Use impersonal passive reporting (\u2018It is said that\u2026\u2019) to stay neutral."],
    outcome:"By the end you can interview someone, then report their claims to a third person without taking a side."
  },
  vocab:[
    {term:"superstition", pos:"noun", def:"a belief that certain actions bring good or bad luck.",
     use:"The adjective \u2018superstitious\u2019 describes the person: \u2018He\u2019s very superstitious\u2019.",
     examples:["There\u2019s a superstition here about yellow underwear at New Year.","She dismisses it all as pure superstition."],
     colloc:"an old / local superstition \u00b7 be superstitious about something"},
    {term:"omen", pos:"noun", def:"a sign that something good or bad will happen.",
     use:"Usually with \u2018good\u2019 or \u2018bad\u2019. The adjective \u2018ominous\u2019 always means threatening.",
     examples:["Rain on your wedding day is a good omen in some cultures.","They took the power cut as a bad omen."],
     colloc:"a good / bad omen \u00b7 an omen of things to come"},
    {term:"hoax", pos:"noun", def:"a trick that makes people believe something untrue.",
     use:"Bigger and more deliberate than a joke, and often public: a fake photo, a false alarm.",
     examples:["The photo turned out to be an elaborate hoax.","Someone made a hoax call to the fire service."],
     colloc:"an elaborate hoax \u00b7 a hoax call \u00b7 turn out to be a hoax"},
    {term:"gullible", pos:"adjective", def:"too ready to believe things, and so easily fooled.",
     use:"Mildly critical. About the person; \u2018far-fetched\u2019 is about the story.",
     examples:["The scam targets gullible investors.","I\u2019m too gullible \u2014 I believe everything I read."],
     colloc:"be gullible enough to \u00b7 prey on gullible people"},
    {term:"far-fetched", pos:"adjective", def:"very unlikely to be true.",
     use:"Use for explanations and stories, not people.",
     examples:["His excuse sounded pretty far-fetched.","It seems far-fetched, but the evidence supports it."],
     colloc:"a far-fetched story / theory / excuse \u00b7 sound far-fetched"},
    {term:"to debunk", pos:"verb", def:"to prove that a belief or story is false.",
     use:"Formal and journalistic; the object is a myth, claim or theory \u2014 not a person.",
     examples:["Scientists debunked the claim within a week.","The channel debunks viral health myths."],
     colloc:"debunk a myth / theory / claim \u00b7 widely debunked"} ],
  grammar:[
    {name:"Reporting clauses", short:"Tense, pronoun and time shifts after said / told.",
     rule:"When you report what someone said earlier, the verb usually moves one step back in time, and pronouns, places and time words change to fit your point of view.",
     form:["is / are \u2192 was / were; do \u2192 did; will \u2192 would; can \u2192 could.","have done / did \u2192 had done.","today \u2192 that day; tomorrow \u2192 the next day; here \u2192 there; this \u2192 that."],
     notes:["\u2018Say\u2019 takes no personal object (He said that\u2026); \u2018tell\u2019 requires one (He told ME that\u2026).","No shift is needed if the statement is still true: \u2018She says the ritual works\u2019.","Reporting verbs carry attitude: admit, claim, insist, deny, warn \u2014 choose one that signals how reliable the claim is."],
     examples:["He admitted (that) he had broken the mirror.","She told me she would never walk under a ladder.","They claimed the house was haunted."],
     watch:"Reported questions lose the question word order: \u2018She asked where I was\u2019, not \u2018where was I\u2019."},
    {name:"Reporting clauses in the passive", short:"\u2018It is said that\u2026\u2019 / \u2018He is believed to\u2026\u2019.",
     rule:"Impersonal passive reporting removes the source of a claim, which makes the statement sound neutral and academic.",
     form:["It + be + said / believed / thought / claimed + that + clause.","Subject + be + said / believed + to + infinitive: He is believed to be innocent.","For an earlier action: He is thought TO HAVE FAKED the whole thing."],
     notes:["Use it when the source is unknown, obvious or unimportant.","\u2018Reportedly\u2019 and \u2018allegedly\u2019 do a similar job in one word.","In speech this can sound distant; in essays and news writing it is standard."],
     examples:["It is said that black cats bring bad luck.","The ritual is believed to protect the home.","He is thought to have faked the whole thing."],
     watch:"\u2018It says that\u2026\u2019 is not the passive \u2014 you need \u2018It IS SAID that\u2026\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"A journalist interviews a self-proclaimed psychic. Afterwards, report to the class what the psychic claimed, using reported speech."},
    {kind:"Debate", text:"Superstitions are harmless fun and nobody is really hurt by them. Agree or disagree."},
    {kind:"Pair work", text:"Share a superstition from your family or region with a partner. Where does it come from, and do you believe it?"} ],
  tips:[
    "Use \u2018It is said / believed / thought that\u2026\u2019 to sound impersonal and academic.",
    "In reported speech, shift the tense back: is \u2192 was, will \u2192 would, have done \u2192 had done.",
    "Common slip: after \u2018say\u2019 you don\u2019t need an object (He said that\u2026); after \u2018tell\u2019 you do (He told me that\u2026)."],
  quiz:{q:"In impersonal reports we say: It ___ that walking under a ladder is unlucky.", options:["is said","says","is saying"], answer:0, explain:"The passive reporting structure is \u2018It is said that\u2026\u2019."} },

{ n:5, title:"MOVIES & TELEVISION", pages:"50\u201362", level:"The Sentence-Adverb Studios", color:"#d1592e", theme:"Movie and TV trends, genres and reviews",
  overview:{
    intro:"Reviewing is an opinion genre, so this unit gives you tools for attitude and intensity: sentence adverbs that comment on the whole statement, and so/such structures that push an adjective to its consequence.",
    goals:["Review films and series with genre-specific vocabulary.","Comment on a whole statement using sentence adverbs.","Express cause and result with so\u2026that / such\u2026that."],
    outcome:"By the end you can give a two-minute spoiler-free review with clear attitude markers and at least two result structures."
  },
  vocab:[
    {term:"plot twist", pos:"noun", def:"an unexpected change in the story.",
     use:"Often \u2018a twist\u2019 on its own. The verb form: \u2018the plot twists\u2019.",
     examples:["The plot twist in the last ten minutes changes everything.","I saw the twist coming from the first scene."],
     colloc:"a clever / predictable plot twist \u00b7 see a twist coming"},
    {term:"spoiler", pos:"noun", def:"information that reveals what happens and ruins the surprise.",
     use:"Warn people with \u2018spoiler alert\u2019 or promise \u2018no spoilers\u2019.",
     examples:["No spoilers, please \u2014 I\u2019m only on episode two.","Spoiler alert: someone doesn\u2019t make it."],
     colloc:"a spoiler alert \u00b7 avoid spoilers \u00b7 spoiler-free review"},
    {term:"to binge-watch", pos:"verb (informal)", def:"to watch many episodes one after another.",
     use:"Very current, always about series. The noun is \u2018a binge\u2019.",
     examples:["We binge-watched the whole season in a weekend.","I try not to binge-watch on weeknights."],
     colloc:"binge-watch a series \u00b7 a weekend binge"},
    {term:"blockbuster", pos:"noun", def:"a very successful, expensive film.",
     use:"About commercial size, not quality \u2014 a blockbuster can still be bad.",
     examples:["Another superhero blockbuster opens this Friday.","The studio needs a blockbuster to survive."],
     colloc:"a summer blockbuster \u00b7 a box-office blockbuster"},
    {term:"overrated", pos:"adjective", def:"praised more than it deserves.",
     use:"Strong opinion word; soften it with \u2018a bit\u2019 or \u2018slightly\u2019. Opposite: underrated.",
     examples:["Honestly, that series is wildly overrated.","It\u2019s a bit overrated, but still enjoyable."],
     colloc:"wildly / hugely overrated \u00b7 vastly underrated"},
    {term:"gripping", pos:"adjective", def:"so exciting that it holds your full attention.",
     use:"For plots, books and performances; not for people.",
     examples:["The first season is absolutely gripping.","A gripping thriller with a superb cast."],
     colloc:"a gripping thriller / drama \u00b7 utterly gripping"} ],
  grammar:[
    {name:"Sentence adverbs", short:"Comment on the whole sentence, not the verb.",
     rule:"A sentence adverb tells the listener your attitude to the whole statement \u2014 how certain, how honest, how surprising it is.",
     form:["Front position + comma (most common): Frankly, the ending disappointed me.","Mid position between commas: The ending, frankly, disappointed me.","End position after a comma: The ending disappointed me, frankly."],
     notes:["Honesty: frankly, honestly, to be fair. Certainty: apparently, presumably, undoubtedly. Reaction: surprisingly, unfortunately, luckily.","Contrast with adverbs of manner: \u2018She spoke frankly\u2019 describes HOW she spoke; \u2018Frankly, she spoke\u2026\u2019 comments on the statement.","One per sentence \u2014 stacking them sounds cluttered."],
     examples:["Frankly, the ending was a huge disappointment.","Apparently, they are already filming a sequel.","Surprisingly, the low-budget film won."],
     watch:"Don\u2019t forget the comma; without it the meaning shifts to manner."},
    {name:"such\u2026that / so\u2026that", short:"Degree plus result.",
     rule:"Both structures link a high degree to its consequence. \u2018So\u2019 goes with an adjective or adverb alone; \u2018such\u2019 goes with a noun phrase.",
     form:["so + adjective/adverb + that: It was so confusing that nobody understood.","such + (a/an) + adjective + noun + that: It was such a long film that I fell asleep.","so much / so many + noun + that: There were so many twists that I lost track."],
     notes:["\u2018That\u2019 can be dropped in speech: \u2018It was so long I fell asleep\u2019.","\u2018so much\u2019 for uncountables, \u2018so many\u2019 for countables.","For formal emphasis you can invert: \u2018So confusing was the plot that\u2026\u2019."],
     examples:["It was such a long film that I fell asleep.","The plot was so confusing that nobody understood it.","She acted so convincingly that she won an award."],
     watch:"\u2018so boring film\u2019 is wrong \u2014 with a noun you need \u2018such a boring film\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"Two film critics on a talk show review a new blockbuster \u2013 one loved it, the other thinks it\u2019s overrated."},
    {kind:"Debate", text:"Streaming platforms have ruined the cinema experience. Argue for or against."},
    {kind:"Pair work", text:"Recommend a film to your partner without spoilers, using \u2018so\u2019 and \u2018such\u2019: \u2018It was so gripping that\u2026\u2019."} ],
  tips:[
    "Put a comma after a sentence adverb at the start: \u2018Honestly, I didn\u2019t like it.\u2019",
    "Remember: \u2018such + (adjective) noun\u2019, but \u2018so + adjective\u2019 alone.",
    "Common slip: avoid \u2018so much + countable\u2019 \u2013 say \u2018so many twists\u2019, not \u2018so much twists\u2019."],
  quiz:{q:"The film was ___ boring that half the audience left.", options:["so","such","very"], answer:0, explain:"Before an adjective on its own we use \u2018so\u2026that\u2019; \u2018such\u2019 needs a noun."} },

{ n:6, title:"MUSICIANS & MUSIC", pages:"63\u201374", level:"The Double-Comparative Concert", color:"#2b7a8c", theme:"Musical tastes, artists and defining success",
  overview:{
    intro:"Music is about change over time \u2014 tastes, careers, technology. The grammar matches: double comparatives express two things changing together, and will/would describe habits then and now.",
    goals:["Talk about taste, talent and success in the music industry.","Link two changing variables with \u2018the more\u2026, the more\u2026\u2019.","Describe present and past habits with will and would."],
    outcome:"By the end you can trace how your taste has changed and argue a case about the music industry with comparative structures."
  },
  vocab:[
    {term:"catchy", pos:"adjective", def:"easy to remember and pleasant to hum.",
     use:"Positive but light \u2014 about the hook, not artistic depth.",
     examples:["The chorus is incredibly catchy.","It\u2019s a catchy tune, but the lyrics are weak."],
     colloc:"a catchy tune / chorus / hook \u00b7 annoyingly catchy"},
    {term:"tone-deaf", pos:"adjective", def:"unable to hear the difference between musical notes.",
     use:"Also used figuratively for someone who misreads a social situation: \u2018a tone-deaf statement\u2019.",
     examples:["I\u2019m completely tone-deaf, so I only listen.","The apology was tone-deaf and made things worse."],
     colloc:"completely tone-deaf \u00b7 a tone-deaf response"},
    {term:"to go viral", pos:"verb phrase", def:"to spread very quickly online.",
     use:"The subject is the content, not the person: \u2018her video went viral\u2019.",
     examples:["The clip went viral overnight.","One remix went viral and changed his career."],
     colloc:"go viral overnight \u00b7 a viral hit \u00b7 go viral on TikTok"},
    {term:"a one-hit wonder", pos:"noun", def:"an artist famous for only a single successful song.",
     use:"Slightly dismissive; can also refer to the song itself.",
     examples:["Critics wrote them off as a one-hit wonder.","She proved she was no one-hit wonder."],
     colloc:"be dismissed as a one-hit wonder"},
    {term:"lyrics", pos:"noun (plural)", def:"the words of a song.",
     use:"Almost always plural, with a plural verb. The writer is a \u2018lyricist\u2019.",
     examples:["The lyrics are surprisingly political.","I misheard the lyrics for years."],
     colloc:"the lyrics are\u2026 \u00b7 write lyrics \u00b7 clever / cheesy lyrics"},
    {term:"to sell out", pos:"phrasal verb", def:"to sell all the tickets for a show.",
     use:"Two meanings: sell every ticket (positive) or abandon your principles for money (very negative).",
     examples:["The concert sold out in ten minutes.","Fans accused the band of selling out."],
     colloc:"sell out a stadium \u00b7 a sold-out show \u00b7 sell out to a label"} ],
  grammar:[
    {name:"Double comparatives", short:"\u2018The more\u2026, the better\u2026\u2019.",
     rule:"Use two comparatives, each introduced by \u2018the\u2019, to show that as one thing changes the other changes with it.",
     form:["The + comparative + clause, the + comparative + clause: The more you practise, the better you get.","Short form with no verb: The louder the crowd, the happier the band.","With nouns: The more tickets they sell, the bigger the venue."],
     notes:["\u2018The\u2019 is obligatory in both halves.","In short forms the verb \u2018be\u2019 is often left out.","\u2018More and more\u2019 / \u2018better and better\u2019 shows continuous change in one variable: \u2018Concerts are getting more and more expensive\u2019."],
     examples:["The more you practise, the better you get.","The louder the crowd, the happier the band.","The harder the song, the more rewarding it is."],
     watch:"\u2018More you practise, better you get\u2019 is wrong \u2014 both halves need \u2018the\u2019."},
    {name:"will & would for habits", short:"Typical behaviour now and in the past.",
     rule:"\u2018Will\u2019 describes present habits and general truths; \u2018would\u2019 describes repeated past actions, often with a nostalgic tone.",
     form:["Present habit: He\u2019ll listen to the same album for weeks.","General truth: Water will boil at 100\u00b0C at sea level.","Past habit: When I was young, I would hum along to everything."],
     notes:["Stressed \u2018will\u2019 shows irritation: \u2018He WILL play it at full volume\u2019.","\u2018Would\u2019 works with actions, not states \u2014 for states use \u2018used to\u2019: \u2018I used to love that band\u2019.","\u2018Used to\u2019 covers both actions and states, so it is the safer choice when unsure."],
     examples:["He\u2019ll listen to the same album on repeat for weeks.","Water will boil at 100\u00b0C at sea level.","When I was young, I would hum along to everything."],
     watch:"Never \u2018I would love it\u2019 for a past state \u2014 say \u2018I used to love it\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"A band manager negotiates a slot at a music festival with the organiser \u2013 discuss the fee, the time and the stage."},
    {kind:"Debate", text:"Streaming platforms pay musicians fairly. Agree or disagree, with reasons."},
    {kind:"Pair work", text:"Tell a partner how your music taste has changed: \u2018I would only listen to\u2026 but now I\u2019ll\u2026\u2019."} ],
  tips:[
    "The double comparative always needs \u2018the\u2019 twice: \u2018the more, the better\u2019 \u2013 not \u2018more, better\u2019.",
    "\u2018Would\u2019 for past habits works with actions, not states \u2013 say \u2018I used to love it\u2019, not \u2018I would love it\u2019.",
    "Common slip: \u2018lyrics\u2019 is normally plural \u2013 \u2018the lyrics are\u2026\u2019, not \u2018the lyrics is\u2026\u2019."],
  quiz:{q:"___ you practise, the better you become.", options:["The more","More","The most"], answer:0, explain:"Double comparatives use \u2018the + comparative\u2019 in both halves: \u2018The more\u2026, the better\u2026\u2019."} },

{ n:7, title:"CHANGING TIMES", pages:"75\u201386", level:"The Relative-Pronoun Crossroads", color:"#b8862b", theme:"Lifestyle change and generational attitudes",
  overview:{
    intro:"This unit compares generations, which means defining people and things precisely \u2014 the job of relative clauses \u2014 and comparing how things are done, the job of as if / the way. Together they let you describe change without vagueness.",
    goals:["Discuss generational change, upbringing and milestones.","Decide when a relative pronoun can be omitted.","Compare real and imagined manner with as if / as though / the way."],
    outcome:"By the end you can narrate how life in your city has changed across two generations, using relative clauses accurately."
  },
  vocab:[
    {term:"to settle down", pos:"phrasal verb", def:"to start a stable, calmer life, often with a family.",
     use:"Also means \u2018become calm\u2019 (\u2018settle down, class!\u2019). Context decides.",
     examples:["They travelled for years before settling down.","He has no plans to settle down yet."],
     colloc:"settle down and start a family \u00b7 ready to settle down"},
    {term:"upbringing", pos:"noun", def:"the way a person is raised as a child.",
     use:"Uncountable-ish: use \u2018a strict upbringing\u2019, never \u2018upbringings\u2019 as a plural list.",
     examples:["She had a strict Catholic upbringing.","Their upbringing taught them to save."],
     colloc:"a strict / religious / privileged upbringing"},
    {term:"generation gap", pos:"noun", def:"the difference in attitudes between older and younger people.",
     use:"Usually with \u2018the\u2019 and \u2018between\u2019.",
     examples:["The generation gap shows most clearly online.","There\u2019s a real generation gap between us on work."],
     colloc:"bridge / close the generation gap"},
    {term:"nostalgia", pos:"noun", def:"a sentimental longing for the past.",
     use:"Uncountable. The adjective \u2018nostalgic\u2019 goes with \u2018about\u2019 or \u2018for\u2019.",
     examples:["The song fills me with nostalgia.","I feel nostalgic about those summers."],
     colloc:"a wave of nostalgia \u00b7 nostalgia for the nineties"},
    {term:"to look back on", pos:"phrasal verb", def:"to remember and reflect on the past.",
     use:"Three parts, so inseparable: \u2018look back on it\u2019, never \u2018look it back on\u2019.",
     examples:["Looking back on it, I made the right choice.","She looks back on those years fondly."],
     colloc:"look back on something fondly / with regret"},
    {term:"milestone", pos:"noun", def:"an important event or turning point in life.",
     use:"For life events and project stages alike: graduation, a first job, a product launch.",
     examples:["Graduating was a huge milestone for my family.","We hit every milestone this quarter."],
     colloc:"reach / hit a milestone \u00b7 a major life milestone"} ],
  grammar:[
    {name:"Optional & required relative pronouns", short:"When you can drop who / that / which.",
     rule:"In a defining relative clause you may omit the pronoun when it is the OBJECT of that clause, but you must keep it when it is the SUBJECT.",
     form:["Object \u2192 optional: the book (that) I read; everything (that) she said.","Subject \u2192 required: the man WHO called; the app THAT crashed.","Non-defining clauses (with commas) always keep the pronoun: My aunt, who lives in Cali, called."],
     notes:["Test it: remove the pronoun. If a verb is left stranded with no subject, the pronoun was the subject and must stay.","\u2018Whose\u2019 is never omitted: the family whose house we bought.","In careful writing, move the preposition to the front: \u2018the house in which we grew up\u2019; in speech it stays at the end."],
     examples:["The house (that) we grew up in has been sold.","The neighbour who moved in is very friendly.","Everything (that) she said turned out to be true."],
     watch:"Never use \u2018that\u2019 in a non-defining clause after a comma \u2014 use who / which."},
    {name:"as if / as though / the way / like", short:"Comparing manner, real and imagined.",
     rule:"Use \u2018as if / as though\u2019 for an appearance or an imagined situation, and \u2018as / the way\u2019 to compare how something is actually done.",
     form:["as if / as though + clause: It looks as though the plan has changed.","Unreal comparison \u2192 past form: He spends money as if he WERE a millionaire.","as / the way + clause: Do it the way your teacher explained."],
     notes:["A present tense after \u2018as if\u2019 suggests the appearance may be real; a past form marks it as clearly unreal.","\u2018Like\u2019 + noun is standard (\u2018like a millionaire\u2019); \u2018like\u2019 + clause is informal.","\u2018As\u2019 + clause is formal: \u2018As we discussed, prices have risen\u2019."],
     examples:["He spends money as if he were a millionaire.","Do it the way your teacher explained.","It looks as though the plan has changed."],
     watch:"In exams and writing, prefer \u2018as if\u2019 to \u2018like\u2019 before a clause."} ],
  speaking:[
    {kind:"Role-play", text:"A grandparent and a grandchild discuss how daily life has changed since the grandparent was young."},
    {kind:"Debate", text:"Life was simpler and better before smartphones. Argue for or against."},
    {kind:"Pair work", text:"Describe a personal milestone and how it changed you, using \u2018nostalgia\u2019 and \u2018look back on\u2019."} ],
  tips:[
    "If you can remove the relative pronoun and the sentence still works, it was the object \u2013 so it\u2019s optional.",
    "After \u2018as if / as though\u2019, a past tense signals something imaginary: \u2018as if he were rich\u2019.",
    "Common slip: in careful English, use \u2018as if\u2019 rather than \u2018like\u2019 before a clause."],
  quiz:{q:"She spends money ___ she were a millionaire.", options:["as if","like of","so that"], answer:0, explain:"\u2018As if\u2019 (+ past tense) describes an unreal or imagined situation."} },

{ n:8, title:"CONSUMER CULTURE", pages:"87\u201398", level:"The Subjunctive Marketplace", color:"#a53a4e", theme:"Shopping habits, marketing and advertising",
  overview:{
    intro:"Shopping and complaining are transactional situations where word order and formality matter. This unit covers how to arrange two objects around a verb, and the subjunctive you need for firm, formal requests and recommendations.",
    goals:["Discuss consumer habits, marketing and value with precise vocabulary.","Order direct and indirect objects naturally.","Use the subjunctive after insist, recommend, demand and \u2018it is essential that\u2026\u2019."],
    outcome:"By the end you can haggle, complain and make a formal written recommendation using the subjunctive correctly."
  },
  vocab:[
    {term:"impulse buy", pos:"noun", def:"something bought suddenly, without any planning.",
     use:"The adverb phrase is \u2018on impulse\u2019: \u2018I bought it on impulse\u2019.",
     examples:["The jacket was a total impulse buy.","Shops put sweets by the till to encourage impulse buys."],
     colloc:"a total impulse buy \u00b7 buy on impulse \u00b7 impulse purchase"},
    {term:"brand loyalty", pos:"noun", def:"the tendency to keep buying the same brand.",
     use:"Marketing vocabulary; the person is \u2018loyal to\u2019 a brand.",
     examples:["Brand loyalty is falling among younger shoppers.","He\u2019s fiercely loyal to that brand."],
     colloc:"build / lose brand loyalty \u00b7 strong brand loyalty"},
    {term:"to haggle", pos:"verb", def:"to argue about a price until you both agree.",
     use:"Use \u2018over\u2019 for the thing and \u2018with\u2019 for the person. Normal at markets, rude in supermarkets.",
     examples:["We haggled over the price for ten minutes.","She haggled with the vendor and got it half price."],
     colloc:"haggle over the price \u00b7 haggle with a seller"},
    {term:"a bargain", pos:"noun", def:"something bought for much less than its usual price.",
     use:"\u2018A bargain\u2019 is the item; \u2018a good deal\u2019 is the transaction. Both are positive.",
     examples:["At that price it\u2019s an absolute bargain.","I picked up a real bargain in the sales."],
     colloc:"an absolute / real bargain \u00b7 a bargain price \u00b7 bargain hunting"},
    {term:"consumerism", pos:"noun", def:"a culture that encourages buying more and more goods.",
     use:"Usually critical, common in essays. The adjective is \u2018consumerist\u2019.",
     examples:["The film is a critique of modern consumerism.","Black Friday is consumerism at its peak."],
     colloc:"rampant / mass consumerism \u00b7 a consumerist society"},
    {term:"target audience", pos:"noun", def:"the specific group a product is aimed at.",
     use:"Also \u2018target market\u2019. The verb: a campaign \u2018targets\u2019 a group.",
     examples:["Our target audience is students under 25.","The ad missed its target audience completely."],
     colloc:"identify / reach a target audience \u00b7 aimed at a target market"} ],
  grammar:[
    {name:"Placement of direct & indirect objects", short:"give me the receipt / give the receipt to me.",
     rule:"Verbs like give, send, show and offer take two objects. You can put the person first with no preposition, or the thing first followed by to / for.",
     form:["Verb + indirect + direct: The clerk gave me a refund.","Verb + direct + to/for + indirect: The clerk gave a refund to me.","With two pronouns, prefer the to-form: Send it to her."],
     notes:["Put new or emphasised information last \u2014 that usually decides which order sounds natural.","\u2018Explain, describe, suggest\u2019 never take the person directly: \u2018explain the rule TO me\u2019, not \u2018explain me the rule\u2019.","\u2018Buy / make / find\u2019 use \u2018for\u2019, not \u2018to\u2019: I bought a gift for her."],
     examples:["The clerk gave me a refund.","The clerk gave a refund to me.","Send it to her (rather than \u2018send her it\u2019)."],
     watch:"\u2018Explain me the problem\u2019 is a very common error \u2014 always \u2018explain the problem to me\u2019."},
    {name:"Verbs in the subjunctive", short:"insist / recommend / it is essential + base form.",
     rule:"After verbs and expressions of demand, advice or importance, the verb in the that-clause stays in its base form for every subject \u2014 no -s, no tense.",
     form:["insist / suggest / recommend / demand / request + that + subject + BASE VERB.","it is essential / vital / important + that + subject + BASE VERB.","Negative: We insist that he NOT be charged."],
     notes:["The base form does not change with he/she/it: \u2018that she arrive\u2019, \u2018that he be refunded\u2019.","British English often prefers \u2018should\u2019: \u2018We recommend that she should try a smaller size\u2019.","\u2018Suggest\u2019 and \u2018recommend\u2019 also take -ing: \u2018We recommend trying a smaller size\u2019."],
     examples:["The manager insisted that the customer be refunded.","It is essential that every receipt be kept.","We recommend that she try a smaller size."],
     watch:"Never \u2018suggest to do\u2019 \u2014 use \u2018suggest that he apply\u2019 or \u2018suggest applying\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"Haggle at a market stall in Cartagena: one student is the vendor, the other is a tourist trying to get a bargain."},
    {kind:"Debate", text:"Advertising manipulates us into buying things we don\u2019t need. Agree or disagree."},
    {kind:"Pair work", text:"Describe your last impulse buy to a partner. Was it a bargain or a waste of money?"} ],
  tips:[
    "In the subjunctive the verb is always the base form \u2013 \u2018he be\u2019, \u2018she arrive\u2019 \u2013 with no -s.",
    "With two pronouns choose the \u2018to\u2019-form: \u2018give it to me\u2019, not \u2018give me it\u2019.",
    "Common slip: after \u2018suggest\u2019 use \u2018that + subjunctive\u2019 or \u2018-ing\u2019 \u2013 \u2018suggest that he apply\u2019 / \u2018suggest applying\u2019, never \u2018suggest to apply\u2019."],
  quiz:{q:"It is essential that every employee ___ present at the meeting.", options:["be","is","was"], answer:0, explain:"After \u2018it is essential that\u2026\u2019 we use the base form (subjunctive): \u2018be\u2019."} },

{ n:9, title:"NATURE", pages:"99\u2013110", level:"The Wherever Wilds", color:"#2b7a8c", theme:"Animals, ethics and the natural world",
  overview:{
    intro:"Environmental discussion needs generalisation: any place, any time, anyone. The \u2018-ever\u2019 words do exactly that, and they also build noun clauses that can act as subject or object \u2014 a compact, advanced structure.",
    goals:["Talk about wildlife, conservation and ethics accurately.","Distinguish when/where from whenever/wherever.","Build noun clauses with whoever, whatever, whichever."],
    outcome:"By the end you can brief a group on protecting a habitat and argue an ethical case using at least three \u2018-ever\u2019 structures."
  },
  vocab:[
    {term:"endangered", pos:"adjective", def:"at serious risk of no longer existing.",
     use:"For species and languages. Stronger stages: \u2018critically endangered\u2019, then \u2018extinct\u2019.",
     examples:["The cotton-top tamarin is critically endangered.","Several endangered species live in that reserve."],
     colloc:"an endangered species \u00b7 critically endangered \u00b7 endangered habitat"},
    {term:"habitat", pos:"noun", def:"the natural home of an animal or plant.",
     use:"Countable. \u2018Habitat loss\u2019 is the standard term for destruction.",
     examples:["Mangroves are a vital habitat for young fish.","Habitat loss is the biggest threat here."],
     colloc:"natural habitat \u00b7 habitat loss / destruction \u00b7 restore a habitat"},
    {term:"to poach", pos:"verb", def:"to hunt or catch animals illegally.",
     use:"The person is a \u2018poacher\u2019; the crime is \u2018poaching\u2019. Also used for hiring staff from rivals.",
     examples:["Gangs poach turtle eggs from the beach.","Rangers arrested two poachers last night."],
     colloc:"poach for ivory \u00b7 illegal poaching \u00b7 anti-poaching patrol"},
    {term:"conservation", pos:"noun", def:"the protection of nature and wildlife.",
     use:"Uncountable. \u2018Conservation\u2019 protects; \u2018preservation\u2019 keeps unchanged.",
     examples:["She works in marine conservation.","Conservation efforts have doubled the population."],
     colloc:"wildlife / marine conservation \u00b7 conservation efforts \u00b7 a conservation area"},
    {term:"biodiversity", pos:"noun", def:"the variety of living things in an area.",
     use:"Uncountable \u2014 never \u2018biodiversities\u2019. Colombia is one of the most biodiverse countries on earth.",
     examples:["The Amazon holds extraordinary biodiversity.","Monoculture farming reduces biodiversity."],
     colloc:"rich / high biodiversity \u00b7 biodiversity loss \u00b7 a biodiversity hotspot"},
    {term:"ecosystem", pos:"noun", def:"a community of living things and their environment.",
     use:"Countable; often \u2018a fragile ecosystem\u2019. Also used metaphorically in business.",
     examples:["The p\u00e1ramo is a fragile ecosystem.","Removing one predator can unbalance the whole ecosystem."],
     colloc:"a fragile / delicate ecosystem \u00b7 disrupt an ecosystem"} ],
  grammar:[
    {name:"whenever / wherever vs when / where", short:"Specific time and place, or any at all.",
     rule:"\u2018When\u2019 and \u2018where\u2019 point to one particular time or place. Adding \u2018-ever\u2019 makes it \u2018at any time / in any place\u2019, or shows that the exact one does not matter.",
     form:["Specific: They return to the beach WHERE they were born.","Any / every: They nest WHEREVER the sand is warm enough.","Concession (\u2018it doesn\u2019t matter\u2019): Wherever you look, there is plastic."],
     notes:["\u2018-ever\u2019 clauses never use \u2018will\u2019 after them: \u2018Call whenever you SPOT the birds\u2019.","\u2018No matter when / where\u2019 is a common paraphrase.","\u2018Whenever\u2019 can also mean \u2018every time that\u2019: \u2018Whenever it rains, the river rises\u2019."],
     examples:["Sea turtles return to the beach where they were born.","They nest wherever the sand is warm enough.","Call me whenever you spot the birds."],
     watch:"Don\u2019t use a future tense inside the -ever clause."},
    {name:"Noun clauses with whoever / whatever", short:"\u2018Any person / thing that\u2026\u2019 as subject or object.",
     rule:"\u2018Whoever, whatever, whichever\u2019 introduce a clause that works like a noun \u2014 it can be the subject or the object of the main verb.",
     form:["As subject: WHOEVER LITTERS HERE will be fined.","As object: Take WHATEVER YOU NEED.","With a noun: The centre helps WHATEVER ANIMAL arrives."],
     notes:["The verb after a subject \u2018whoever\u2019 is singular: \u2018Whoever wants to help is welcome\u2019.","\u2018Whomever\u2019 exists for object position but sounds very formal; \u2018whoever\u2019 is normal.","\u2018Whichever\u2019 implies a limited set of choices; \u2018whatever\u2019 is open."],
     examples:["Whoever litters here will be fined.","The rescue centre helps whatever animal arrives.","We\u2019ll support whoever protects the reserve."],
     watch:"Don\u2019t add a second subject: \u2018Whoever litters here, HE will be fined\u2019 is wrong."} ],
  speaking:[
    {kind:"Role-play", text:"A park ranger briefs a group of international tourists before a hike in Tayrona National Park."},
    {kind:"Debate", text:"Zoos do more harm than good for wildlife. Argue for or against."},
    {kind:"Pair work", text:"Tell a partner about one endangered animal you would protect and why, using \u2018whatever\u2019 and \u2018wherever\u2019."} ],
  tips:[
    "\u2018-ever\u2019 words add flexibility: whenever = at any time, wherever = in any place.",
    "\u2018whoever / whatever\u2019 can be the subject or object of their clause: \u2018Whoever calls\u2026\u2019 / \u2018Call whoever you like.\u2019",
    "Common slip: Colombia is one of the most biodiverse countries \u2013 use \u2018biodiversity\u2019 (uncountable), never \u2018biodiversities\u2019."],
  quiz:{q:"Take ___ you need from the supply box.", options:["whatever","however","whoever"], answer:0, explain:"\u2018Whatever\u2019 = any thing that; it introduces a noun clause as the object of \u2018take\u2019."} },

{ n:10, title:"LANGUAGE", pages:"111\u2013122", level:"The Passive-Voice Peaks", color:"#6b5ba8", theme:"Effective communication and attitudes toward language",
  overview:{
    intro:"When you write about language, the doer is often unknown or irrelevant \u2014 which is what the passive is for. This unit systematises the passive across tenses and then tackles the agreement problems quantifiers create.",
    goals:["Talk about fluency, dialect, register and communication strategies.","Form and choose the passive across tenses, including \u2018have something done\u2019.","Make verbs agree correctly after quantifiers like none of, a number of, each of."],
    outcome:"By the end you can write an objective paragraph about language use in your country with accurate passives and agreement."
  },
  vocab:[
    {term:"fluent", pos:"adjective", def:"able to speak a language easily and well.",
     use:"Fluent = smooth, not necessarily error-free. Use \u2018fluent IN Portuguese\u2019.",
     examples:["She\u2019s fluent in three languages.","He speaks fluent but heavily accented English."],
     colloc:"fluent in a language \u00b7 become fluent \u00b7 fluent speaker"},
    {term:"dialect", pos:"noun", def:"a form of a language spoken in a particular region.",
     use:"A dialect has its own grammar and vocabulary; an \u2018accent\u2019 is only pronunciation.",
     examples:["Costa Rican and Colombian Spanish differ in dialect.","The play is written in a regional dialect."],
     colloc:"a regional / local dialect \u00b7 speak in dialect"},
    {term:"slang", pos:"noun", def:"very informal words used by a particular group.",
     use:"Uncountable: \u2018a piece of slang\u2019, not \u2018a slang\u2019. Avoid in formal writing.",
     examples:["Teenage slang changes every year.","Some slang doesn\u2019t travel between cities."],
     colloc:"street / teenage slang \u00b7 use slang \u00b7 slang expression"},
    {term:"mother tongue", pos:"noun", def:"the first language you learned as a child.",
     use:"Also \u2018native language\u2019 or \u2018L1\u2019. Some people have two.",
     examples:["My mother tongue is Spanish, but I dream in English sometimes.","Teaching is best in a child\u2019s mother tongue at first."],
     colloc:"mother-tongue speaker \u00b7 in your mother tongue"},
    {term:"to pick up (a language)", pos:"phrasal verb", def:"to learn it informally, without lessons.",
     use:"Suggests ease and no study. Separable: \u2018pick it up\u2019.",
     examples:["He picked up Italian while working in Rome.","Kids pick languages up incredibly fast."],
     colloc:"pick up a language / an accent / a few phrases"},
    {term:"to get your point across", pos:"idiom", def:"to make people understand what you mean.",
     use:"About successful communication despite limited words \u2014 exactly what a C1 speaker needs.",
     examples:["I don\u2019t know all the words, but I get my point across.","Use examples to get your point across faster."],
     colloc:"get your point across clearly \u00b7 struggle to get your point across"} ],
  grammar:[
    {name:"Overview of passives", short:"be + past participle, across all tenses.",
     rule:"Use the passive when the action or its result matters more than who performed it, or when the agent is unknown, obvious or deliberately hidden.",
     form:["Present: English IS SPOKEN here. Past: The report WAS WRITTEN last week.","Perfect / future / modal: has been published, will be translated, must be signed.","Causative: I HAD my essay CHECKED by a tutor."],
     notes:["Add \u2018by + agent\u2019 only when the doer adds information.","Only transitive verbs have a passive \u2014 \u2018happen\u2019 and \u2018arrive\u2019 cannot be passive.","Overusing the passive makes writing heavy; mix it with active sentences."],
     examples:["Over 60 languages are spoken in Colombia.","The report was written last week.","I had my essay checked by a tutor (have something done)."],
     watch:"Don\u2019t drop \u2018be\u2019: \u2018The report written last week\u2019 is not a full passive sentence."},
    {name:"Subject-verb agreement with quantifiers", short:"Which noun does the verb follow?",
     rule:"After quantifiers with \u2018of\u2019, the verb normally agrees with the noun that follows \u2018of\u2019 \u2014 but a few phrases have fixed behaviour.",
     form:["Some / most / all / half of + singular \u2192 singular verb; + plural \u2192 plural verb.","Each / every one / neither / either of + plural noun \u2192 SINGULAR verb.","A number of + plural \u2192 plural verb; THE number of + plural \u2192 singular verb."],
     notes:["\u2018None of\u2019 takes either: \u2018none of it is\u2019, \u2018none of them are\u2019 \u2014 both accepted.","Don\u2019t let a long phrase between subject and verb confuse you: \u2018The list of new words IS long\u2019.","\u2018There is / are\u2019 agrees with the first noun after it."],
     examples:["None of the homework was difficult.","A number of students were absent.","Each of the answers is correct."],
     watch:"\u2018Each of the students ARE\u2019 is wrong \u2014 \u2018each\u2019 is always singular."} ],
  speaking:[
    {kind:"Role-play", text:"The organiser of a language-exchange meetup welcomes international students and explains the ground rules."},
    {kind:"Debate", text:"English is becoming too dominant as a global language. Agree or disagree."},
    {kind:"Pair work", text:"Tell a partner about a time you couldn\u2019t find a word \u2013 how did you get your point across?"} ],
  tips:[
    "Use the passive to sound objective, or when the doer is obvious or unknown: \u2018The results were published.\u2019",
    "\u2018A number of\u2019 takes a plural verb; \u2018the number of\u2019 takes a singular verb.",
    "Common slip: \u2018none of\u2019 can take a singular OR plural verb \u2013 both \u2018none of it is\u2019 and \u2018none of them are\u2019 are accepted."],
  quiz:{q:"A number of students ___ absent from class today.", options:["were","was","is"], answer:0, explain:"\u2018A number of\u2019 + plural noun takes a plural verb: \u2018were\u2019."} },

{ n:11, title:"EXCEPTIONAL PEOPLE", pages:"123\u2013133", level:"The Compound-Adjective Summit", color:"#c0662b", theme:"Role models, values and high achievers",
  overview:{
    intro:"Describing remarkable people economically is the goal here. Compound adjectives pack a whole description into one hyphenated word, and their superlatives let you rank people precisely instead of repeating \u2018very\u2019.",
    goals:["Describe character, achievement and resilience with strong vocabulary.","Build compound adjectives and hyphenate them correctly.","Form superlatives of compound adjectives."],
    outcome:"By the end you can introduce a role model in a short speech using at least four compound adjectives, one of them superlative."
  },
  vocab:[
    {term:"role model", pos:"noun", def:"a person others admire and try to copy.",
     use:"Two words, no hyphen. Often \u2018a positive role model FOR young people\u2019.",
     examples:["Teachers are role models whether they like it or not.","She\u2019s a positive role model for young athletes."],
     colloc:"a positive / poor role model \u00b7 a role model for someone"},
    {term:"to look up to", pos:"phrasal verb", def:"to admire and respect someone.",
     use:"Three parts, inseparable: \u2018look up to her\u2019. Opposite: \u2018look down on\u2019 (despise).",
     examples:["I\u2019ve always looked up to my grandmother.","Younger players look up to him."],
     colloc:"look up to a parent / mentor \u00b7 look down on someone"},
    {term:"determined", pos:"adjective", def:"firmly decided to succeed and not give up.",
     use:"Followed by \u2018to + verb\u2019. The noun is \u2018determination\u2019.",
     examples:["She was determined to finish the degree.","His determination impressed everyone."],
     colloc:"determined to succeed \u00b7 fiercely determined \u00b7 sheer determination"},
    {term:"resilient", pos:"adjective", def:"able to recover quickly from difficulties.",
     use:"For people, communities and systems. Noun: \u2018resilience\u2019.",
     examples:["Small businesses here are remarkably resilient.","Resilience matters more than talent in the long run."],
     colloc:"remarkably resilient \u00b7 build resilience \u00b7 a resilient community"},
    {term:"to overcome", pos:"verb", def:"to succeed in dealing with a problem.",
     use:"Irregular: overcome \u2013 overcame \u2013 overcome.",
     examples:["She overcame serious injuries to compete again.","They overcame every obstacle in their way."],
     colloc:"overcome an obstacle / a fear / adversity"},
    {term:"groundbreaking", pos:"adjective", def:"new and very different in an important way.",
     use:"One word, no hyphen. For work, research and art \u2014 not people.",
     examples:["Her groundbreaking research changed the field.","A groundbreaking album for its time."],
     colloc:"groundbreaking research / work / discovery"} ],
  grammar:[
    {name:"Compound adjectives", short:"Two words, one hyphen, one meaning.",
     rule:"A compound adjective joins two or more words into a single describing word placed before a noun, normally with a hyphen.",
     form:["adjective/adverb + participle: quick-thinking leader, well-known scientist, hard-working student.","number + singular noun: a five-year plan, a ten-page report.","noun + adjective: a world-famous athlete, a sugar-free drink."],
     notes:["Hyphenate before the noun; after the verb the hyphen usually disappears: \u2018the singer is well known\u2019.","Adverbs ending in -ly are NOT hyphenated: \u2018a highly respected expert\u2019.","The number stays singular: \u2018a five-year plan\u2019, never \u2018a five-years plan\u2019."],
     examples:["She is a quick-thinking leader.","They signed a three-year contract.","He is a world-famous athlete."],
     watch:"Missing hyphens change meaning: \u2018a well known author\u2019 vs \u2018a well-known author\u2019."},
    {name:"Superlative compound adjectives", short:"best-known, hardest-working, most widely respected.",
     rule:"To make a compound adjective superlative, put the superlative on the FIRST element, or use \u2018most\u2019 when the first element cannot take -est.",
     form:["First element takes -est / best / worst: the hardest-working student, the best-known artist.","With \u2018most\u2019: the most highly regarded expert, the most widely respected award.","Comparative works the same way: a better-known writer, a harder-working team."],
     notes:["Say \u2018best-known\u2019, not \u2018most well-known\u2019, in careful English.","Keep the hyphen in the superlative form: \u2018the best-known\u2019.","Add \u2018in / of\u2019 to limit the comparison: \u2018the hardest-working person ON the team\u2019."],
     examples:["She is the best-known writer of her generation.","He is the hardest-working person on the team.","It is the most widely respected award in the field."],
     watch:"Never double the superlative: \u2018the most hardest-working\u2019 is wrong."} ],
  speaking:[
    {kind:"Role-play", text:"At an award ceremony, introduce a national hero (for example a Colombian scientist, athlete or artist) to an international audience."},
    {kind:"Debate", text:"Natural talent matters more than hard work. Argue for or against."},
    {kind:"Pair work", text:"Describe someone you look up to, using at least three compound adjectives (hard-working, open-minded, quick-thinking\u2026)."} ],
  tips:[
    "Hyphenate before a noun: \u2018a well-known singer\u2019; but after the verb, drop it: \u2018the singer is well known\u2019.",
    "Say \u2018best-known\u2019, not \u2018most well-known\u2019, for the superlative.",
    "Common slip: keep the first number singular \u2013 \u2018a five-year plan\u2019, not \u2018a five-years plan\u2019."],
  quiz:{q:"Gabriel Garc\u00eda M\u00e1rquez is the ___ writer Colombia has produced.", options:["best-known","most well-known","well-knownest"], answer:0, explain:"The standard superlative compound adjective is \u2018best-known\u2019."} },

{ n:12, title:"BUSINESS MATTERS", pages:"134\u2013145", level:"The Inversion Boardroom", color:"#2f6d3a", theme:"Entrepreneurship, negotiation and the ideal job",
  overview:{
    intro:"The final unit is about professional register. Conditional inversion (\u2018Should you need\u2026\u2019) is the single fastest way to sound formal in emails and interviews, and adverb clauses of condition let you set precise terms in a negotiation.",
    goals:["Discuss startups, negotiation and career priorities with business vocabulary.","Replace \u2018if\u2019 with inversion in formal conditionals.","Set conditions with provided that, as long as, unless and in case."],
    outcome:"By the end you can run a negotiation and write a formal follow-up email using inversion and at least two conditional linkers."
  },
  vocab:[
    {term:"startup", pos:"noun", def:"a new company, often small and fast-growing.",
     use:"One word in business English. \u2018Scale-up\u2019 describes the next stage.",
     examples:["She left the bank to join a fintech startup.","Most startups fail in the first three years."],
     colloc:"launch / fund a startup \u00b7 a tech startup \u00b7 startup costs"},
    {term:"to break even", pos:"verb phrase", def:"to make just enough money to cover your costs.",
     use:"No object. \u2018Break-even point\u2019 is hyphenated as a noun.",
     examples:["We expect to break even in month nine.","They haven\u2019t broken even yet."],
     colloc:"break even within a year \u00b7 the break-even point"},
    {term:"to close a deal", pos:"verb phrase", def:"to successfully complete a business agreement.",
     use:"\u2018Close\u2019 = finish successfully; \u2018seal the deal\u2019 is a stronger synonym.",
     examples:["We closed the deal on Friday afternoon.","He\u2019s brilliant at closing deals."],
     colloc:"close / seal / land a deal \u00b7 a deal falls through"},
    {term:"to think outside the box", pos:"idiom", def:"to think in a creative, original way.",
     use:"Common in meetings, slightly clich\u00e9d \u2014 pair it with a concrete example.",
     examples:["We need to think outside the box on pricing.","Her solution was real outside-the-box thinking."],
     colloc:"think outside the box \u00b7 outside-the-box thinking"},
    {term:"revenue", pos:"noun", def:"the total income a business earns.",
     use:"Revenue is money in; \u2018profit\u2019 is what remains after costs. Uncountable.",
     examples:["Revenue grew 30% but profit fell.","Most of our revenue comes from subscriptions."],
     colloc:"annual revenue \u00b7 generate revenue \u00b7 revenue stream"},
    {term:"to negotiate", pos:"verb", def:"to discuss something in order to reach an agreement.",
     use:"Negotiate WITH a person, OVER an issue. Noun: negotiation(s).",
     examples:["We negotiated a better delivery date.","She negotiated with three suppliers at once."],
     colloc:"negotiate a contract / salary \u00b7 enter into negotiations"} ],
  grammar:[
    {name:"Subject-verb inversion in conditionals", short:"Were I you\u2026 / Had we known\u2026 / Should you need\u2026",
     rule:"In formal English you can delete \u2018if\u2019 and invert the subject with were, had or should. The meaning is identical; the register is higher.",
     form:["If I were in charge \u2192 WERE I in charge, I would raise salaries.","If we had invested \u2192 HAD WE invested earlier, we would have profited.","If you should need help \u2192 SHOULD YOU need help, please email us."],
     notes:["Only were, had and should invert \u2014 you cannot say \u2018Wanted I a raise\u2026\u2019.","Negatives are not contracted: \u2018Had we not invested\u2026\u2019, never \u2018Hadn\u2019t we invested\u2026\u2019.","\u2018Should you\u2026\u2019 is standard in business emails for polite offers of help."],
     examples:["Were I in charge, I would raise salaries.","Had we invested earlier, we would have profited.","Should you have any questions, please email us."],
     watch:"Keep it for writing and formal speech; in casual conversation it sounds stiff."},
    {name:"Adverb clauses of condition", short:"provided that, as long as, unless, in case.",
     rule:"These linkers state the condition under which something is true, and each carries a slightly different nuance.",
     form:["provided (that) / as long as = only if this is true: You can leave early provided the work is done.","unless = if not: Unless sales improve, we\u2019ll cut costs.","in case = as a precaution: Take a card in case you need to pay."],
     notes:["\u2018In case\u2019 \u2260 \u2018if\u2019: \u2018Take a card in case\u2019 (a precaution) vs \u2018Take a card if you need it\u2019 (only then).","No future tense in the condition clause: \u2018as long as you HIT the target\u2019.","Don\u2019t use a second negative after \u2018unless\u2019."],
     examples:["You\u2019ll get the bonus as long as you hit the target.","Unless sales improve, we\u2019ll cut costs.","Take a card in case you need to pay."],
     watch:"\u2018Unless you don\u2019t hurry\u2019 is a double negative \u2014 say \u2018Unless you hurry\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"A salary negotiation between a job candidate and an HR manager at an international company in Bogot\u00e1."},
    {kind:"Debate", text:"Money is the best motivator at work. Argue for or against."},
    {kind:"Pair work", text:"Pitch a business idea for your city to a partner in 60 seconds, then answer their questions."} ],
  tips:[
    "Inversion (\u2018Were I you\u2026\u2019) sounds formal \u2013 great for writing and interviews.",
    "\u2018provided that\u2019 and \u2018as long as\u2019 both mean \u2018only if this condition is true\u2019.",
    "Common slip: after \u2018unless\u2019 don\u2019t add a second negative \u2013 \u2018Unless you hurry\u2026\u2019 (not \u2018Unless you don\u2019t hurry\u2026\u2019)."],
  quiz:{q:"___ I you, I would accept the offer immediately.", options:["Were","Was","If"], answer:0, explain:"Formal conditional inversion drops \u2018if\u2019 and uses \u2018Were\u2019 for all subjects: \u2018Were I you\u2026\u2019."} }
];
